algorithms.pseudocode:
Input: Matrix A (m x n over Z/qZ), modulus q, dimension n
Output: List of vectors v in (Z/qZ)^n with A*v = 0

for each v in (Z/qZ)^n:
  if A*v mod q == 0:
    add v to kernel
return kernel

algorithms.code:
def compute_kernel(matrix, q, n):
    import itertools
    kernel = []
    for v in itertools.product(range(q), repeat=n):
        if all(sum(a*b for a,b in zip(row,v)) % q == 0 for row in matrix):
            kernel.append(v)
    return kernel

def evaluate_fo_consistency(reencrypt, recover, ciphertext):
    k, m = recover(ciphertext)
    return reencrypt(k, m) == ciphertext

def compute_game_hop_bound(real_game, hybrid_game, predicate, weight_fn, domain):
    sum_real = sum(weight_fn(c) * real_game(c) for c in domain)
    sum_hybrid = sum(weight_fn(c) * hybrid_game(c) for c in domain)
    lhs = abs(sum_real - sum_hybrid)
    bad_weight = sum(weight_fn(c) for c in domain if not predicate(c))
    return {'lhs': lhs, 'rhs': bad_weight, 'bound_holds': lhs <= bad_weight + 1e-12}
